contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address recipient, uint256 amount) public payable {
        require(caller != address(0));
        (bool s, ) = address(c).call{value: amount}("");
        require(s);

        uint256 balBefore = address(c).balance;
        uint256 senderBalBefore = caller.balance;

        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }

        if (caller == msg.sender) {
            assert(!reverted && address(c).balance == 0 && c.owner() == caller);
        } else {
            assert(reverted && address(c).balance == balBefore && caller.balance == senderBalBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

