        c = _c;
    }

    function run(address caller, address recipient, uint256 amount) public payable {
        require(caller != address(0));
        require(address(c).balance == 0);
        require(address(this).balance >= amount);

        // fund c so the owner withdrawal has someth
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        address ownerBefore = c.owner();
        uint256 cBalBefore = address(c).balance;

        // deciding call: withdrawAll as the chosen caller
        bool reverted;
        if (caller == address(this)) {
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        } else {
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        }

        address ownerAfter = c.owner();
        uint256 cBalAfter = address(c).balance;

        bool isOwner = (caller == ownerBefore);

        assert(
            (isOwner && !reverted && ownerAfter == ownerBefore && cBalBefore == amount && cBalAfter == 0) ||
            (!isOwner && reverted && ownerAfter == ownerBefore && cBalAfter == cBalBefore)
        );
    }

    receive() external payable {}
}

